// 3. UTF-8 & Base64URL Encoding Helpers
function base64url(input) {
  let str = typeof input === 'string' ? input : JSON.stringify(input);
  return Buffer.from(str, 'utf-8')
    .toString('base64')
    .replace(/=/g, '')
    .replace(/\+/g, '-')
    .replace(/\//g, '_');
}

function base64urlBuffer(buf) {
  return buf.toString('base64')
    .replace(/=/g, '')
    .replace(/\+/g, '-')
    .replace(/\//g, '_');
}

// 4. HMAC-SHA256 Implementation
function hmacSha256(keyStr, messageStr) {
  function rightRotate(v, a) { return (v >>> a) | (v << (32 - a)); }
  const K = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2
  ];

  function sha256Bytes(bytes) {
    const H = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
    const l = bytes.length, bitLen = l * 8;
    const padLen = (l % 64 < 56) ? 56 - (l % 64) : 120 - (l % 64);
    const padded = new Uint8Array(l + padLen + 8);
    padded.set(bytes);
    padded[l] = 0x80;
    const view = new DataView(padded.buffer);
    view.setUint32(padded.length - 4, bitLen & 0xffffffff, false);
    view.setUint32(padded.length - 8, Math.floor(bitLen / 0x100000000), false);
    for (let i = 0; i < padded.length; i += 64) {
      const w = new Uint32Array(64);
      for (let t = 0; t < 16; t++) w[t] = view.getUint32(i + t * 4, false);
      for (let t = 16; t < 64; t++) {
        const s0 = rightRotate(w[t-15], 7) ^ rightRotate(w[t-15], 18) ^ (w[t-15] >>> 3);
        const s1 = rightRotate(w[t-2], 17) ^ rightRotate(w[t-2], 19) ^ (w[t-2] >>> 10);
        w[t] = (w[t-16] + s0 + w[t-7] + s1) | 0;
      }
      let [a, b, c, d, e, f, g, h] = H;
      for (let t = 0; t < 64; t++) {
        const S1 = rightRotate(e, 6) ^ rightRotate(e, 11) ^ rightRotate(e, 25);
        const ch = (e & f) ^ (~e & g);
        const temp1 = (h + S1 + ch + K[t] + w[t]) | 0;
        const S0 = rightRotate(a, 2) ^ rightRotate(a, 13) ^ rightRotate(a, 22);
        const maj = (a & b) ^ (a & c) ^ (b & c);
        const temp2 = (S0 + maj) | 0;
        h = g; g = f; f = e; e = (d + temp1) | 0;
        d = c; c = b; b = a; a = (temp1 + temp2) | 0;
      }
      H[0] = (H[0] + a) | 0; H[1] = (H[1] + b) | 0; H[2] = (H[2] + c) | 0; H[3] = (H[3] + d) | 0;
      H[4] = (H[4] + e) | 0; H[5] = (H[5] + f) | 0; H[6] = (H[6] + g) | 0; H[7] = (H[7] + h) | 0;
    }
    const res = new Uint8Array(32);
    const resView = new DataView(res.buffer);
    for (let i = 0; i < 8; i++) resView.setUint32(i * 4, H[i], false);
    return res;
  }

  let key = Buffer.from(keyStr, 'utf-8');
  if (key.length > 64) key = sha256Bytes(key);
  if (key.length < 64) { const tmp = new Uint8Array(64); tmp.set(key); key = tmp; }
  const oKey = new Uint8Array(64), iKey = new Uint8Array(64);
  for (let i = 0; i < 64; i++) { oKey[i] = key[i] ^ 0x5c; iKey[i] = key[i] ^ 0x36; }
  const msg = Buffer.from(messageStr, 'utf-8');
  const inner = new Uint8Array(64 + msg.length);
  inner.set(iKey); inner.set(msg, 64);
  const outer = new Uint8Array(64 + 32);
  outer.set(oKey); outer.set(sha256Bytes(inner), 64);
  return Buffer.from(sha256Bytes(outer));
}

// 5. Construct JWT Header & Payload
const now = Math.floor(Date.now() / 1000);
const header = { alg: "HS256", typ: "JWT" };
const payload = {
  iss: apiKey,
  sub: "n8n-server",
  nbf: now - 10,
  exp: now + 3600,
  video: { 
    roomCreate: true, 
    roomAdmin: true,
    roomList: true
  }
};

const unsignedToken = `${base64url(header)}.${base64url(payload)}`;
const signatureBuffer = hmacSha256(apiSecret, unsignedToken);
const signature = base64urlBuffer(signatureBuffer);
const jwtToken = `${unsignedToken}.${signature}`;

// 6. Return values to n8n pipeline
return [{
  json: {
    room_name: roomName,
    livekit_token: jwtToken
  }
}];

